<?php require __DIR__.'/../config.php';admin_required();if($_SERVER['REQUEST_METHOD']!=='POST')exit;verify_csrf();$id=(int)$_POST['id'];$status=$_POST['status']??'open';$priority=$_POST['priority']??'normal';$note=trim($_POST['admin_note']??'');if(!in_array($status,['open','pending','resolved','closed'],true)||!in_array($priority,['low','normal','high','urgent'],true))exit('Invalid update.');$s=db()->prepare("UPDATE tickets SET status=?,priority=?,admin_note=? WHERE id=?");$s->execute([$status,$priority,$note,$id]);flash('Request updated successfully.');header("Location: view.php?id=$id");